        for (size_t i = 0; i < HV_WORDS; ++i) hv.words[i] = splitmix64(state);
        return hv;
    }

    inline uint32_t hamming(const Hypervec8192& other) const {
        uint32_t d = 0;
        for (size_t i = 0; i < HV_WORDS; ++i) {
